-- reference.fasta is produced by sequence_workload() from the registered GenBank input.
-- fasta
SELECT count(*)::VARCHAR AS output_hits, sum(hit.cost)::VARCHAR AS edit_cost_sum, sum(hash(row_id, hit.pattern_idx, hit.text_start, hit.text_end, hit.pattern_start, hit.pattern_end, hit.cost, hit.strand, hit.cigar)::HUGEINT)::VARCHAR AS fingerprint FROM (SELECT 0::UBIGINT AS row_id, hit FROM sassy_panel_search_fasta('reference.fasta', ['GCTTTTCATTCTGACTGCAACGG','ATTAAAGTGCTGGCAATCATCGG','AACTTTGGCGACCCCTTCACGGG','TGCTGGCAATTCCTTTGCTCCGG','AGTAATCGCTACGTTCCCCGCGG','ATTCCGGCATTTGCCGTAACCGG','TAACCTGCGTGAAAGCCAGCAGG','GCTTTTAGAGCAACGAGACACGG'], 2, alphabet := 'dna'));
-- crispr
SELECT count(*)::VARCHAR AS output_hits, sum(hit.cost)::VARCHAR AS edit_cost_sum, sum(hash(row_id, hit.pattern_idx, hit.text_start, hit.text_end, hit.pattern_start, hit.pattern_end, hit.cost, hit.strand, hit.cigar)::HUGEINT)::VARCHAR AS fingerprint FROM (SELECT 0::UBIGINT AS row_id, hit FROM sassy_crispr_panel_search_fasta('reference.fasta', ['GCTTTTCATTCTGACTGCAANGG','ATTAAAGTGCTGGCAATCATNGG','AACTTTGGCGACCCCTTCACNGG','TGCTGGCAATTCCTTTGCTCNGG','AGTAATCGCTACGTTCCCCGNGG','ATTCCGGCATTTGCCGTAACNGG','TAACCTGCGTGAAAGCCAGCNGG','GCTTTTAGAGCAACGAGACANGG'], 2));
-- relational
SELECT count(*)::VARCHAR AS output_hits, sum(hit.cost)::VARCHAR AS edit_cost_sum, sum(hash(row_id, hit.pattern_idx, hit.text_start, hit.text_end, hit.pattern_start, hit.pattern_end, hit.cost, hit.strand, hit.cigar)::HUGEINT)::VARCHAR AS fingerprint FROM (SELECT row_id, UNNEST(sassy_matches(guide, sequence, 2, alphabet := 'dna')) AS hit FROM targets);
